allNext.text:
/-- `◦φ ≡ ¬•¬φ`, all-path next (OOPSLA 2023 p. 13): every successor matches φ.
`◦⊥` is `¬•⊤`: no successor. -/
def allNext (φ : P) : P := ∼(sNext (∼φ))

stepStatements.text:
/-- The successors a step function lists for ground configurations are ground configurations. -/
def OutputsGround (c : Semantics) (f : StepFn) : Prop :=
  ∀ t, GroundConfig c t → ∀ t' ∈ f t, GroundConfig c t'

/-- Γ_D ⊧ c → •c' for every listed successor c' of every ground configuration c. -/
def StepSound (c : Semantics) (p : Presentation) (f : StepFn) : Prop :=
  ∀ t, GroundConfig c t → ∀ t' ∈ f t, ΓD c p ⊧ (den t ⇒ sNext (den t'))

/-- Γ_D ∪ Γ_closure ⊧ c → ◦(c'₁ ∨ … ∨ c'ₙ) where `f c = [c'₁, …, c'ₙ]`; for `f c = []`,
Γ_D ∪ Γ_closure ⊧ c → ¬•⊤ (c is stuck). -/
def StepComplete (c : Semantics) (p : Presentation) (f : StepFn) : Prop :=
  ∀ t, GroundConfig c t → (ΓD c p ∪ Γclosure c p) ⊧ (den t ⇒ allNext (disjList ((f t).map den)))

